import { apiFetch } from './client'
import type { Task, TaskPriority } from './types'

export interface TaskCreateInput {
  assigned_to: string
  title: string
  due_date?: string | null
  priority?: TaskPriority
  external_reference?: string | null
}

export interface TaskUpdateInput {
  title?: string | null
  due_date?: string | null
  priority?: TaskPriority | null
}

export function createTask(input: TaskCreateInput): Promise<Task> {
  return apiFetch<Task>('/api/v1/tasks', {
    method: 'POST',
    body: JSON.stringify(input),
  })
}

export function getTasks(limit = 50, offset = 0): Promise<Task[]> {
  return apiFetch<Task[]>(`/api/v1/tasks?limit=${limit}&offset=${offset}`)
}

export function getTask(taskId: string): Promise<Task> {
  return apiFetch<Task>(`/api/v1/tasks/${taskId}`)
}

export function updateTask(taskId: string, input: TaskUpdateInput): Promise<Task> {
  return apiFetch<Task>(`/api/v1/tasks/${taskId}`, {
    method: 'PATCH',
    body: JSON.stringify(input),
  })
}

export function completeTask(taskId: string): Promise<Task> {
  return apiFetch<Task>(`/api/v1/tasks/${taskId}/complete`, { method: 'POST' })
}

export function cancelTask(taskId: string): Promise<Task> {
  return apiFetch<Task>(`/api/v1/tasks/${taskId}/cancel`, { method: 'POST' })
}

import { apiFetch } from './client'
import type { User } from './types'

export function getUsers(role?: string): Promise<User[]> {
  const query = role ? `?role=${encodeURIComponent(role)}` : ''
  return apiFetch<User[]>(`/api/v1/users${query}`)
}

// Hand-written mirrors of backend Pydantic response schemas.
// UUID and ISO-datetime fields are typed as `string` — the backend already
// validates them; the frontend only needs the shape for the compiler.

export interface GeoJSONPolygon {
  type: 'Polygon'
  coordinates: number[][][]
}

export interface Zone {
  id: string
  name: string
  boundary: GeoJSONPolygon
}

export interface ZoneAssignment {
  id: string
  zone_id: string
  rep_id: string
}

export type TaskPriority = 'LOW' | 'MEDIUM' | 'HIGH'

export interface Task {
  id: string
  assigned_to: string
  title: string
  due_date: string | null
  status: string
  priority: string
  external_reference: string | null
  created_at: string
  completed_at: string | null
}

export type GoalMetricType = 'VISIT_COUNT' | 'TASK_COUNT' | 'SALES_VALUE'

export interface Goal {
  id: string
  rep_id: string
  metric_type: string
  target: number
  period_start: string
  period_end: string
  manual_value: number | null
  created_at: string
}

export interface GoalProgress {
  goal_id: string
  rep_id: string
  metric_type: string
  target: number
  achieved: number
  period_start: string
  period_end: string
}

export interface ZoneViolation {
  id: string
  rep_id: string
  zone_id: string
  detected_at: string
  resolved_at: string | null
}

export interface PushSubscription {
  id: string
  manager_id: string
  endpoint: string
  created_at: string
}

export interface VapidPublicKey {
  vapid_public_key: string
}

export interface Ping {
  id: string
  recorded_at: string
  latitude: number
  longitude: number
  accuracy: number | null
}

export interface LatestPing {
  id: string
  rep_id: string
  recorded_at: string
  latitude: number
  longitude: number
  accuracy: number | null
}

export interface User {
  id: string
  email: string
  role: string
}

